        {/* Блок отзывов */}
        <div className="mt-8 max-w-6xl mx-auto">
          <ProductReviews productId={product.id} productName={product.name} />
        </div>
      </div>
      </main>
      <Footer />
      <CartSidebar />
      <MobileNav />
      <ChatLauncher />
    </div>
  );
}

