// Amazon-level Product Configuration System

export type VariantOption = {
  value: string;
  label: string;
  priceModifier: number;
  image?: string; // Опционально для цветов/материалов
  disabled?: boolean; // Для зависимостей
};

export type Variant = {
  id: string;
  label: string;
  type: 'color' | 'size' | 'material' | 'custom';
  required: boolean;
  options: VariantOption[];
};

export type ToggleOption = {
  id: string;
  label: string;
  description?: string;
  type: 'toggle';
  price: number;
  defaultValue?: boolean;
  dependencies?: {
    variant?: { [key: string]: string }; // Если выбран вариант
    option?: { [key: string]: boolean }; // Если включена опция
    priceModifier?: number; // Изменение цены при зависимости
  };
};

export type SelectOption = {
  id: string;
  label: string;
  description?: string;
  type: 'select';
  values: Array<{
    value: string;
    label: string;
    price: number;
    disabled?: boolean;
  }>;
  defaultValue?: string;
  dependencies?: {
    variant?: { [key: string]: string };
    option?: { [key: string]: boolean };
  };
};

export type ProductOption = ToggleOption | SelectOption;

export type ProductConfiguration = {
  variants?: Variant[];
  options?: ProductOption[];
};

export type SelectedConfiguration = {
  variants: { [key: string]: string | null };
  options: { [key: string]: boolean | string | null };
};

export type ConfiguredProduct = {
  productId: string;
  name: string;
  basePrice: number;
  configuration: SelectedConfiguration;
  finalPrice: number;
  quantity: number;
  image: string;
};

// Utility type для расширенного продукта
export type ConfigurableProduct = {
  id: string;
  name: string;
  basePrice: number;
  image: string;
  configuration?: ProductConfiguration;
};

// Функция расчета итоговой цены
export function calculateConfiguredPrice(
  basePrice: number,
  configuration: ProductConfiguration | undefined,
  selected: SelectedConfiguration
): number {
  if (!configuration) return basePrice;

  let price = basePrice;

  // Добавляем цену вариантов
  if (configuration.variants) {
    configuration.variants.forEach((variant) => {
      const selectedValue = selected.variants[variant.id];
      if (selectedValue) {
        const option = variant.options.find((opt) => opt.value === selectedValue);
        if (option) {
          price += option.priceModifier;
        }
      }
    });
  }

  // Добавляем цену опций
  if (configuration.options) {
    configuration.options.forEach((option) => {
      if (option.type === 'toggle') {
        const isSelected = selected.options[option.id] as boolean;
        if (isSelected) {
          // Проверяем зависимости для изменения цены
          let optionPrice = option.price;

          if (option.dependencies?.variant) {
            const dependencyMet = Object.entries(option.dependencies.variant).every(
              ([variantId, value]) => selected.variants[variantId] === value
            );
            if (dependencyMet && option.dependencies.priceModifier) {
              optionPrice += option.dependencies.priceModifier;
            }
          }

          price += optionPrice;
        }
      } else if (option.type === 'select') {
        const selectedValue = selected.options[option.id] as string;
        if (selectedValue) {
          const value = option.values.find((v) => v.value === selectedValue);
          if (value) {
            price += value.price;
          }
        }
      }
    });
  }

  return price;
}

// Функция проверки зависимостей
export function checkDependencies(
  option: ProductOption,
  selected: SelectedConfiguration
): boolean {
  if (!option.dependencies) return true;

  // Проверка зависимостей от вариантов
  if (option.dependencies.variant) {
    const variantDependencyMet = Object.entries(option.dependencies.variant).every(
      ([variantId, value]) => selected.variants[variantId] === value
    );
    if (!variantDependencyMet) return false;
  }

  // Проверка зависимостей от других опций
  if (option.dependencies.option) {
    const optionDependencyMet = Object.entries(option.dependencies.option).every(
      ([optionId, value]) => selected.options[optionId] === value
    );
    if (!optionDependencyMet) return false;
  }

  return true;
}

// Функция получения описания конфигурации для отображения
export function getConfigurationSummary(
  configuration: ProductConfiguration | undefined,
  selected: SelectedConfiguration
): string[] {
  if (!configuration) return [];

  const summary: string[] = [];

  // Добавляем выбранные варианты
  if (configuration.variants) {
    configuration.variants.forEach((variant) => {
      const selectedValue = selected.variants[variant.id];
      if (selectedValue) {
        const option = variant.options.find((opt) => opt.value === selectedValue);
        if (option) {
          summary.push(`${variant.label}: ${option.label}`);
        }
      }
    });
  }

  // Добавляем выбранные опции
  if (configuration.options) {
    configuration.options.forEach((option) => {
      if (option.type === 'toggle') {
        const isSelected = selected.options[option.id] as boolean;
        if (isSelected) {
          summary.push(option.label);
        }
      } else if (option.type === 'select') {
        const selectedValue = selected.options[option.id] as string;
        if (selectedValue) {
          const value = option.values.find((v) => v.value === selectedValue);
          if (value) {
            summary.push(`${option.label}: ${value.label}`);
          }
        }
      }
    });
  }

  return summary;
}

src/types/product-configuration.ts:
/**
 * Расширенная система конфигурации товаров
 * Поддерживает варианты с изображениями и дополнительные опции
 */

export interface VariantOption {
  value: string;
  label: string;
  priceModifier: number;
  image?: string;
  default?: boolean;
  disabled?: boolean;
}

export interface VariantGroup {
  label: string;
  required: boolean;
  options: VariantOption[];
}

export interface ToggleOption {
  label: string;
  type: "toggle";
  price: number;
  description?: string;
  default?: boolean;
  disabled?: boolean;
  disabledMessage?: string;
}

export interface SelectOption {
  label: string;
  type: "select";
  required?: boolean;
  options: Array<{
    value: string;
    label: string;
    priceModifier: number;
    default?: boolean;
    disabled?: boolean;
  }>;
}

export type ProductOption = ToggleOption | SelectOption;

export interface ProductConfiguration {
  variants?: {
    [key: string]: VariantGroup;
  };
  options?: {
    [key: string]: ProductOption;
  };
}

export interface SelectedConfiguration {
  variants: {
    [key: string]: string;
  };
  options: {
    [key: string]: string | boolean;
  };
}

export interface PriceCalculation {
  basePrice: number;
  variantsTotal: number;
  optionsTotal: number;
  finalPrice: number;
  breakdown: Array<{
    label: string;
    value: string;
    price: number;
  }>;
}

/**
 * Рассчитывает финальную цену на основе выбранной конфигурации
 * @param basePrice - базовая цена товара
 * @param configuration - конфигурация товара
 * @param selected - выбранная пользователем конфигурация
 * @returns объект с детализацией цены
 */
export function calculatePrice(
  basePrice: number,
  configuration: ProductConfiguration,
  selected: SelectedConfiguration
): PriceCalculation {
  if (basePrice < 0) {
    throw new Error("Base price cannot be negative");
  }

  let variantsTotal = 0;
  let optionsTotal = 0;
  const breakdown: Array<{ label: string; value: string; price: number }> = [];

  if (configuration.variants) {
    Object.entries(configuration.variants).forEach(([key, group]) => {
      const selectedValue = selected.variants[key];
      if (!selectedValue) return;

      const option = group.options.find((opt) => opt.value === selectedValue);
      if (!option) return;

      variantsTotal += option.priceModifier;
      breakdown.push({
        label: group.label,
        value: option.label,
        price: option.priceModifier,
      });
    });
  }

  if (configuration.options) {
    Object.entries(configuration.options).forEach(([key, option]) => {
      const selectedValue = selected.options[key];
      if (selectedValue === undefined || selectedValue === null) return;

      if (option.type === "toggle") {
        if (selectedValue === true) {
          optionsTotal += option.price;
          breakdown.push({
            label: option.label,
            value: "Да",
            price: option.price,
          });
        }
      } else if (option.type === "select") {
        const selectedOption = option.options.find((opt) => opt.value === selectedValue);
        if (!selectedOption) return;

        optionsTotal += selectedOption.priceModifier;
        breakdown.push({
          label: option.label,
          value: selectedOption.label,
          price: selectedOption.priceModifier,
        });
      }
    });
  }

  const finalPrice = basePrice + variantsTotal + optionsTotal;

  return {
    basePrice,
    variantsTotal,
    optionsTotal,
    finalPrice,
    breakdown,
  };
}

/**
 * Получает изображение для выбранного цвета
 */
export function getImageForColor(
  configuration: ProductConfiguration,
  selectedColor: string,
  defaultImage: string
): string {
  if (!configuration.variants?.color) {
    return defaultImage;
  }

  const colorOption = configuration.variants.color.options.find(
    opt => opt.value === selectedColor
  );

  return colorOption?.image || defaultImage;
}

/**
 * Инициализирует конфигурацию значениями по умолчанию
 */
export function initializeConfiguration(
  configuration: ProductConfiguration
): SelectedConfiguration {
  const selected: SelectedConfiguration = {
    variants: {},
    options: {},
  };

  // Устанавливаем варианты по умолчанию
  if (configuration.variants) {
    Object.entries(configuration.variants).forEach(([key, group]) => {
      const defaultOption = group.options.find(opt => opt.default);
      if (defaultOption) {
        selected.variants[key] = defaultOption.value;
      } else if (group.options.length > 0) {
        selected.variants[key] = group.options[0].value;
      }
    });
  }

  // Устанавливаем опции по умолчанию
  if (configuration.options) {
    Object.entries(configuration.options).forEach(([key, option]) => {
      if (option.type === 'toggle') {
        selected.options[key] = option.default || false;
      } else if (option.type === 'select') {
        const defaultOption = option.options.find(opt => opt.default);
        if (defaultOption) {
          selected.options[key] = defaultOption.value;
        } else if (option.options.length > 0) {
          selected.options[key] = option.options[0].value;
        }
      }
    });
  }

  return selected;
}

/**
 * Проверяет, заполнены ли все обязательные поля
 */
export function validateConfiguration(
  configuration: ProductConfiguration,
  selected: SelectedConfiguration
): { valid: boolean; errors: string[] } {
  const errors: string[] = [];

  // Проверяем обязательные варианты
  if (configuration.variants) {
    Object.entries(configuration.variants).forEach(([key, group]) => {
      if (group.required && !selected.variants[key]) {
        errors.push(`Выберите ${group.label.toLowerCase()}`);
      }
    });
  }

  // Проверяем обязательные опции
  if (configuration.options) {
    Object.entries(configuration.options).forEach(([key, option]) => {
      if (option.type === 'select' && option.required && !selected.options[key]) {
        errors.push(`Выберите ${option.label.toLowerCase()}`);
      }
    });
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

